//! P4 export options and a SelectionContext-only read adapter. Legacy encoders stay unchanged.
use crate::{Shared,Res,locked,core};use serde_json::Value;
pub(crate) fn validate(value:&Value)->Res<()>{let map=value.as_object().ok_or("INVALID_OUTPUT")?;let allowed=["kind","format","width","height","quality","fit","background","maxBytes"];if map.keys().any(|key|!allowed.contains(&key.as_str())){return Err("INVALID_OUTPUT".into())}if !value["format"].is_null()&&!matches!(value["format"].as_str(),Some("webp"|"jpeg"|"png")){return Err("INVALID_OUTPUT".into())}if value["width"].is_null()!=value["height"].is_null(){return Err("INVALID_OUTPUT".into())}if !value["width"].is_null(){let w=value["width"].as_u64().filter(|n|(1..=16000).contains(n)).ok_or("INVALID_OUTPUT")?;let h=value["height"].as_u64().filter(|n|(1..=16000).contains(n)).ok_or("INVALID_OUTPUT")?;if w*h>120000000{return Err("INVALID_OUTPUT".into())}}if !value["quality"].is_null()&&!value["quality"].as_u64().is_some_and(|n|(1..=100).contains(&n)){return Err("INVALID_OUTPUT".into())}if !value["maxBytes"].is_null()&&!value["maxBytes"].as_u64().is_some_and(|n|n<=1000000000){return Err("INVALID_OUTPUT".into())}if !value["fit"].is_null()&&!matches!(value["fit"].as_str(),Some("pad"|"crop")){return Err("INVALID_OUTPUT".into())}if !value["background"].is_null(){crate::editor_pixels::color(&value["background"])?;}Ok(())}
pub(crate) fn preset(value:&Value,width:u32,height:u32)->Res<core::ExportPreset>{validate(value)?;Ok(core::ExportPreset{format:value["format"].as_str().unwrap_or("webp").into(),width:value["width"].as_u64().map(|n|n as u32).unwrap_or(width),height:value["height"].as_u64().map(|n|n as u32).unwrap_or(height),quality:value["quality"].as_u64().unwrap_or(90) as u8,max_bytes:value["maxBytes"].as_u64().unwrap_or(0),fit:value["fit"].as_str().unwrap_or("pad").into(),background:if value["background"].is_null(){[255,255,255]}else{crate::editor_pixels::color(&value["background"])?},output_dir:String::new()})}
pub(crate) fn preview(s:&Shared,args:Value)->Res<Value>{let map=args.as_object().ok_or("INVALID_EXPORT_PREVIEW")?;if map.keys().any(|key|!["projectId","context","preset","edit","previewIndex"].contains(&key.as_str())){return Err("INVALID_EXPORT_PREVIEW".into())}let pid=args["projectId"].as_str().ok_or("PROJECT_REQUIRED")?;let root=locked(s)?.root.clone();let ids=crate::frontend_ops::context_ids(s,pid,&args["context"],false)?;let index=if args["previewIndex"].is_null(){0}else{args["previewIndex"].as_u64().filter(|n|*n<(ids.len() as u64)).ok_or("INVALID_PREVIEW_INDEX")? as usize};if args["preset"]["width"].is_null()||args["preset"].get("kind").is_some(){return Err("INVALID_OUTPUT".into())}let preset=preset(&args["preset"],1,1)?;let edit:core::Edit=serde_json::from_value(args["edit"].clone()).map_err(|_|"INVALID_EDIT")?;let store=locked(s)?;if store.root!=root{return Err("DATA_ROOT_CHANGED".into())}store.export_preview(pid,&ids[index],&edit,&preset)}
#[cfg(test)]mod tests{use super::*;use serde_json::json;use std::sync::{Arc,Mutex,atomic::{AtomicBool,AtomicU64}};
fn setup()->(tempfile::TempDir,Shared,String,Value){let temp=tempfile::tempdir().unwrap();let store=core::Store::open(temp.path().join("data"),"test").unwrap();let p=store.create("export adapter".into()).unwrap();let source=temp.path().join("source.png");image::RgbaImage::from_pixel(80,120,image::Rgba([30,70,120,255])).save(&source).unwrap();let p=store.import(&p.id,vec![source.to_string_lossy().into()],&AtomicBool::new(false),|_,_|{}).unwrap().project;let aid=p.assets[0].id.clone();let context=json!({"page":"library","mentions":[],"selected":[aid],"editorAssetId":null,"filter":{"folder":"","tag":"","status":"","q":"","sort":""},"filteredCount":1,"resolvedTarget":{"source":"selected","ids":[aid]},"fileNames":["source.png"]});(temp,Arc::new(crate::AppState{store:Mutex::new(store),cancel:AtomicBool::new(false),local_job:Mutex::new(()),preview_epoch:AtomicU64::new(0)}),p.id,context)}
#[test]fn export_options_reject_paths_partial_sizes_and_invalid_quality(){for value in [json!({"outputDir":"C:/private"}),json!({"width":80}),json!({"width":16000,"height":16000}),json!({"quality":0}),json!({"quality":101}),json!({"background":[256,0,0]}),json!({"maxBytes":-1})]{assert!(validate(&value).is_err());}let p=preset(&json!({"quality":37}),20000,10).unwrap();assert_eq!((p.width,p.height,p.quality),(20000,10,37));}
#[test]fn selection_preview_reuses_exact_legacy_encoding_without_writing_versions(){let(_temp,s,pid,context)=setup();let options=json!({"format":"jpeg","width":90,"height":70,"fit":"crop","quality":37,"maxBytes":0,"background":[240,230,220]});let edit=core::Edit{exposure:0.2,..Default::default()};let before=locked(&s).unwrap().load(&pid).unwrap();let legacy=locked(&s).unwrap().export_preview(&pid,&before.assets[0].id,&edit,&preset(&options,1,1).unwrap()).unwrap();let response=preview(&s,json!({"projectId":pid,"context":context,"preset":options,"edit":edit})).unwrap();assert_eq!(response,legacy);assert_eq!(response["quality"],37);let after=locked(&s).unwrap().load(&pid).unwrap();assert_eq!(before.assets[0].sha256,after.assets[0].sha256);assert_eq!(before.assets[0].versions.len(),after.assets[0].versions.len());}
#[test]fn preview_rejects_out_of_scope_assets_context_paths_and_legacy_locators(){let(_temp,s,pid,context)=setup();let args=json!({"projectId":pid,"context":context,"preset":{"format":"png","width":20,"height":30},"edit":core::Edit::default()});let mut bad=args.clone();bad["previewIndex"]=json!(1);assert!(preview(&s,bad).is_err());let mut bad=args.clone();bad["assetId"]=json!(uuid::Uuid::new_v4().to_string());assert!(preview(&s,bad).is_err());let mut bad=args.clone();bad["context"]["fileNames"]=json!(["C:/private/source.png"]);assert!(preview(&s,bad).is_err());let mut bad=args.clone();bad["context"]["selected"]=json!([uuid::Uuid::new_v4().to_string()]);bad["context"]["resolvedTarget"]["ids"]=bad["context"]["selected"].clone();assert!(preview(&s,bad).is_err());let(_other,other,_,_)=setup();assert!(preview(&other,args).is_err());}
#[test]fn preview_index_stays_inside_the_real_multi_image_context(){let(temp,s,pid,mut context)=setup();let source=temp.path().join("other.png");image::RgbaImage::from_pixel(80,120,image::Rgba([190,20,70,255])).save(&source).unwrap();let p=locked(&s).unwrap().import(&pid,vec![source.to_string_lossy().into()],&AtomicBool::new(false),|_,_|{}).unwrap().project;let ids=p.assets.iter().map(|a|a.id.clone()).collect::<Vec<_>>();context["selected"]=json!(ids);context["resolvedTarget"]["ids"]=json!(ids);context["fileNames"]=json!(["source.png","other.png"]);context["filteredCount"]=json!(2);let options=json!({"format":"png","width":20,"height":30});let expected=locked(&s).unwrap().export_preview(&pid,&ids[1],&core::Edit::default(),&preset(&options,1,1).unwrap()).unwrap();let actual=preview(&s,json!({"projectId":pid,"context":context,"preset":options,"edit":core::Edit::default(),"previewIndex":1})).unwrap();assert_eq!(actual,expected);}

}
